import{_ as s,o as t,c as i,a3 as e}from"./chunks/framework.BlfGB29P.js";const k=JSON.parse('{"title":"RAG 原理与边界","description":"从知识来源、索引、检索、上下文和生成五项职责理解 RAG，辨析它能解决的问题、成立条件、失败边界与替代方案。","frontmatter":{"title":"RAG 原理与边界","description":"从知识来源、索引、检索、上下文和生成五项职责理解 RAG，辨析它能解决的问题、成立条件、失败边界与替代方案。","framework":"通用 RAG 架构","version":"Python 3.12 / LangChain 1.x 概念基线","verified_at":"2026-07-29","source":["https://arxiv.org/abs/2005.11401","https://docs.langchain.com/oss/python/deepagents/retrieval"],"article":{"type":"concept","structure":"concept"}},"headers":[],"relativePath":"py-agent/knowledge/rag-foundations-data/rag-principles-boundaries.md","filePath":"py-agent/knowledge/rag-foundations-data/rag-principles-boundaries.md","lastUpdated":1785318762000}'),n={name:"py-agent/knowledge/rag-foundations-data/rag-principles-boundaries.md"};function r(l,a,p,d,h,o){return t(),i("div",null,[...a[0]||(a[0]=[e(`<h1 id="rag-原理与边界" tabindex="-1">RAG 原理与边界 <a class="header-anchor" href="#rag-原理与边界" aria-label="Permalink to &quot;RAG 原理与边界&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>检索增强生成（Retrieval-Augmented Generation，RAG）不是一种新的语言模型，而是一种应用架构：系统先从外部知识源找出与问题相关的证据，再把证据连同问题交给模型生成回答。</p><p>它解决的是“模型当前需要哪些外部信息”这一问题。它不能让模型自动拥有正确知识，也不能把不可靠的数据源变成事实。</p><h2 id="_1-rag-解决的问题" tabindex="-1">1. RAG 解决的问题 <a class="header-anchor" href="#_1-rag-解决的问题" aria-label="Permalink to &quot;1. RAG 解决的问题&quot;">​</a></h2><p>语言模型的参数保存了训练得到的统计规律，但应用经常需要处理三类参数之外的信息：</p><ul><li>模型训练结束后才出现的新信息；</li><li>企业内部、个人或受权限保护的信息；</li><li>回答时必须定位原文、版本和来源的信息。</li></ul><p>把所有资料直接塞进一次请求通常也不可行：上下文窗口有限，噪声会稀释证据，输入成本与延迟也会增长。RAG 在回答前增加一个选择过程，只把候选知识中的相关部分送入模型。</p><p>RAG 的目标可以写成两步：</p><ol><li>根据问题 <code>q</code>，从知识集合 <code>D</code> 中取得证据 <code>C = retrieve(q, D)</code>；</li><li>根据问题和证据生成回答 <code>a = generate(q, C)</code>。</li></ol><p>检索和生成是两个可独立失败、也应独立评测的阶段。</p><h2 id="_2-系统组成与职责" tabindex="-1">2. 系统组成与职责 <a class="header-anchor" href="#_2-系统组成与职责" aria-label="Permalink to &quot;2. 系统组成与职责&quot;">​</a></h2><h3 id="_2-1-知识来源" tabindex="-1">2.1 知识来源 <a class="header-anchor" href="#_2-1-知识来源" aria-label="Permalink to &quot;2.1 知识来源&quot;">​</a></h3><p>知识来源是系统认可的数据原点，例如产品手册、数据库记录、工单或网页。它负责提供内容和来源信息，不负责决定模型最终如何回答。</p><p>每份源数据至少需要稳定身份、内容、更新时间和权限属性。没有来源身份，系统便无法正确更新、删除或引用旧内容。</p><h3 id="_2-2-索引" tabindex="-1">2.2 索引 <a class="header-anchor" href="#_2-2-索引" aria-label="Permalink to &quot;2.2 索引&quot;">​</a></h3><p>索引把源文档转换成适合搜索的表示。常见表示包括关键词倒排表、Embedding 向量和图结构。</p><p>索引不是知识本身，而是知识的查询加速结构。源文档变化后，旧索引不会自动正确，必须经过增量更新或重建。</p><h3 id="_2-3-retriever" tabindex="-1">2.3 Retriever <a class="header-anchor" href="#_2-3-retriever" aria-label="Permalink to &quot;2.3 Retriever&quot;">​</a></h3><p>Retriever 接受查询，返回一组候选文档或 Chunk。它负责召回、过滤和排序候选，不负责生成自然语言答案。</p><p>一个有用的返回项通常包含：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>content: 候选文本</span></span>
<span class="line"><span>metadata: source_id、version、section、tenant_id 等</span></span>
<span class="line"><span>score: 可选的相关性信号</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p><code>score</code> 的尺度取决于检索后端，不能默认不同算法或不同索引的分数可以直接比较。</p><h3 id="_2-4-上下文构建器" tabindex="-1">2.4 上下文构建器 <a class="header-anchor" href="#_2-4-上下文构建器" aria-label="Permalink to &quot;2.4 上下文构建器&quot;">​</a></h3><p>上下文构建器把检索结果转换为模型输入。它会执行去重、截断、排序、来源标记和 Token 预算控制。</p><p>“检索到了”不等于“模型看到了”。候选在上下文组装时可能被删除、截断或挤出窗口，因此最终送入模型的证据必须单独记录。</p><h3 id="_2-5-生成模型" tabindex="-1">2.5 生成模型 <a class="header-anchor" href="#_2-5-生成模型" aria-label="Permalink to &quot;2.5 生成模型&quot;">​</a></h3><p>生成模型根据问题、指令和证据组织回答。模型仍然可能忽略证据、错误归因或补写证据中不存在的内容。</p><p>因此，生成阶段需要明确规则，例如证据不足时拒答、引用必须对应给定来源、不能把外部文本中的指令当作系统指令。</p><h2 id="_3-两条运行链路" tabindex="-1">3. 两条运行链路 <a class="header-anchor" href="#_3-两条运行链路" aria-label="Permalink to &quot;3. 两条运行链路&quot;">​</a></h2><h3 id="_3-1-离线-ingestion-链路" tabindex="-1">3.1 离线 Ingestion 链路 <a class="header-anchor" href="#_3-1-离线-ingestion-链路" aria-label="Permalink to &quot;3.1 离线 Ingestion 链路&quot;">​</a></h3><p>离线链路把知识源转换成可查询索引：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>发现数据 → 加载 → 解析与规范化 → 切分 → 表示 → 写入索引</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>“离线”表示它通常不位于一次用户问答的关键路径，不表示只能批量或定时执行。实时增量写入仍属于 Ingestion 职责。</p><h3 id="_3-2-在线查询链路" tabindex="-1">3.2 在线查询链路 <a class="header-anchor" href="#_3-2-在线查询链路" aria-label="Permalink to &quot;3.2 在线查询链路&quot;">​</a></h3><p>在线链路处理一次问题：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户问题 → 查询处理 → 检索 → 过滤/融合/重排</span></span>
<span class="line"><span>         → 上下文组装 → 模型生成 → 引用与结果校验</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>两条链路通过索引中的数据契约连接。若离线链路写入的元数据与在线过滤条件不一致，检索即使能运行，也可能持续返回错误范围的数据。</p><h2 id="_4-rag-成立的条件" tabindex="-1">4. RAG 成立的条件 <a class="header-anchor" href="#_4-rag-成立的条件" aria-label="Permalink to &quot;4. RAG 成立的条件&quot;">​</a></h2><p>RAG 能改善回答，至少需要满足四个条件：</p><ol><li><strong>可检索</strong>：问题与相关证据之间存在可被关键词、向量或结构查询捕捉的信号。</li><li><strong>可定位</strong>：文档被切成足以独立解释、又没有过度丢失上下文的单元。</li><li><strong>可用</strong>：检索到的证据能在输入预算内清楚呈现给模型。</li><li><strong>可约束</strong>：生成策略要求模型以证据为依据，并能在证据不足时表达不确定性。</li></ol><p>这些条件形成一条串联系统。生成模型更强不能补救被权限过滤掉的正确文档，重排器也不能找回候选生成阶段完全没有召回的内容。</p><h2 id="_5-rag-与相邻方案" tabindex="-1">5. RAG 与相邻方案 <a class="header-anchor" href="#_5-rag-与相邻方案" aria-label="Permalink to &quot;5. RAG 与相邻方案&quot;">​</a></h2><table tabindex="0"><thead><tr><th>需求</th><th>更直接的方案</th><th>原因</th></tr></thead><tbody><tr><td>查询精确订单状态</td><td>调用订单 API</td><td>结构化实时数据不应先转成文本再猜测</td></tr><tr><td>回答内部手册问题并引用原文</td><td>RAG</td><td>需要按问题选择非公开证据</td></tr><tr><td>固定格式转换或分类</td><td>Prompt、结构化输出或小模型</td><td>不一定需要外部知识检索</td></tr><tr><td>改变模型长期行为或风格</td><td>微调</td><td>目标是参数行为，不是临时注入事实</td></tr><tr><td>让模型执行退款</td><td>工具调用与工作流</td><td>RAG 只读取证据，不代表获得执行权限</td></tr><tr><td>少量、稳定且很短的规则</td><td>直接放入系统上下文</td><td>引入索引可能增加不必要复杂度</td></tr></tbody></table><p>RAG、工具调用和微调可以组合，但三者解决的不是同一问题：RAG 提供证据，工具读取或改变外部状态，微调改变模型行为分布。</p><h2 id="_6-主要失败边界" tabindex="-1">6. 主要失败边界 <a class="header-anchor" href="#_6-主要失败边界" aria-label="Permalink to &quot;6. 主要失败边界&quot;">​</a></h2><h3 id="_6-1-数据失败" tabindex="-1">6.1 数据失败 <a class="header-anchor" href="#_6-1-数据失败" aria-label="Permalink to &quot;6.1 数据失败&quot;">​</a></h3><p>文档缺失、版本过期、解析乱码或元数据错误，会让正确答案根本不存在于可检索集合中。此时调整 Prompt 无法修复根因。</p><h3 id="_6-2-检索失败" tabindex="-1">6.2 检索失败 <a class="header-anchor" href="#_6-2-检索失败" aria-label="Permalink to &quot;6.2 检索失败&quot;">​</a></h3><p>查询与文档用词不同、Chunk 粒度不合适、过滤条件错误或近似索引召回不足，都会让正确证据落在候选集之外。</p><h3 id="_6-3-上下文失败" tabindex="-1">6.3 上下文失败 <a class="header-anchor" href="#_6-3-上下文失败" aria-label="Permalink to &quot;6.3 上下文失败&quot;">​</a></h3><p>系统可能取回正确证据，却因去重、截断或排序把它排除在最终上下文之外。必须同时观察“检索候选”和“模型实际输入”。</p><h3 id="_6-4-生成失败" tabindex="-1">6.4 生成失败 <a class="header-anchor" href="#_6-4-生成失败" aria-label="Permalink to &quot;6.4 生成失败&quot;">​</a></h3><p>即使上下文正确，模型仍可能错误综合多个来源、引用错位或在证据之外推断。检索指标不能代替忠实性和引用评测。</p><h3 id="_6-5-安全与权限失败" tabindex="-1">6.5 安全与权限失败 <a class="header-anchor" href="#_6-5-安全与权限失败" aria-label="Permalink to &quot;6.5 安全与权限失败&quot;">​</a></h3><p>检索结果中的文本是不可信数据，可能包含 Prompt Injection。权限过滤必须由应用或存储层强制执行，不能依赖模型“不要泄露”的指令。</p><h2 id="_7-用执行轨迹观察-rag" tabindex="-1">7. 用执行轨迹观察 RAG <a class="header-anchor" href="#_7-用执行轨迹观察-rag" aria-label="Permalink to &quot;7. 用执行轨迹观察 RAG&quot;">​</a></h2><p>一次问答不应只保存最终文本。至少记录以下轨迹：</p><div class="language-python vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">trace </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;question&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;退款申请可以撤销吗？&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;query&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;退款申请 撤销 条件&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;candidate_ids&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;policy-v3#refund-2&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;faq-v5#refund-8&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;selected_ids&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;policy-v3#refund-2&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;context_chars&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">486</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;answer&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;提交后、审核前可以撤销。&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;citations&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;policy-v3#refund-2&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p>这段数据不实现 RAG，而是暴露各阶段结果。出现错误时，可以先判断正确证据是否存在、是否被召回、是否进入上下文，再判断模型是否忠实使用它。</p><h2 id="_8-验证方法与常见误解" tabindex="-1">8. 验证方法与常见误解 <a class="header-anchor" href="#_8-验证方法与常见误解" aria-label="Permalink to &quot;8. 验证方法与常见误解&quot;">​</a></h2><p>基础验证至少分三层：</p><table tabindex="0"><thead><tr><th>层级</th><th>核心问题</th><th>示例信号</th></tr></thead><tbody><tr><td>数据</td><td>正确知识是否进入系统</td><td>解析成功率、版本覆盖率、删除同步率</td></tr><tr><td>检索</td><td>正确证据是否进入候选</td><td>Recall@k、MRR、过滤正确率</td></tr><tr><td>生成</td><td>回答是否依据给定证据</td><td>答案正确性、忠实性、引用准确率</td></tr></tbody></table><p>常见误解包括：</p><ul><li><strong>“使用向量数据库就是 RAG”</strong>：向量数据库只承担索引和搜索职责。</li><li><strong>“Top-k 越大越好”</strong>：更多候选会增加噪声和上下文成本。</li><li><strong>“有引用就不会幻觉”</strong>：引用可能与断言不对应，仍需验证引用归因。</li><li><strong>“RAG 会更新模型知识”</strong>：外部证据只在本次调用中进入上下文，不会自动改写模型参数。</li><li><strong>“RAG 只需离线评测一次”</strong>：数据、查询分布、Embedding 和模型版本变化都会使质量漂移。</li></ul><p>理解这些边界后，后续文章才能分别优化数据、Chunk、索引、Retriever、上下文和生成，而不是把所有失败统称为“模型答错了”。</p>`,66)])])}const u=s(n,[["render",r]]);export{k as __pageData,u as default};
